import HEDGE_EVENTS from "../assets/data/levels/hedges/events.json";
import HEDGE_LEVEL from "../assets/data/levels/hedges/hedges.json";
import HEDGE_BACKGROUND from "../assets/data/levels/hedges/hedges_background.png";
import HEDGE_FOREGROUND from "../assets/data/levels/hedges/hedges_foreground.png";
import HEDGE_NPCS from "../assets/data/levels/hedges/npcs.json";
import TREES1_JSON from "../assets/data/spot_the_diff/trees1.json";
import TREES1_IMG from "../assets/data/spot_the_diff/trees1.png";
import TREES2_JSON from "../assets/data/spot_the_diff/trees2.json";
import TREES2_IMG from "../assets/data/spot_the_diff/trees2.png";
import TREES3_JSON from "../assets/data/spot_the_diff/trees3.json";
import TREES3_IMG from "../assets/data/spot_the_diff/trees3.png";
import TREES4_JSON from "../assets/data/spot_the_diff/trees4.json";
import TREES4_IMG from "../assets/data/spot_the_diff/trees4.png";
import BULB_JSON from "../assets/images/npcs/hedges/bulb.json";
import BULB_IMG from "../assets/images/npcs/hedges/bulb.png";
import ROCK_JSON from "../assets/images/npcs/hedges/rock.json";
import ROCK_IMG from "../assets/images/npcs/hedges/rock.png";
import SEED_JSON from "../assets/images/npcs/hedges/seed.json";
import SEED_IMG from "../assets/images/npcs/hedges/seed.png";
import STUMP_JSON from "../assets/images/npcs/hedges/stump.json";
import STUMP_IMG from "../assets/images/npcs/hedges/stump.png";
import VSPROUT_JSON from "../assets/images/npcs/hedges/vsprout.json";
import VSPROUT_IMG from "../assets/images/npcs/hedges/vsprout.png";
import FOUNTAIN_JSON from "../assets/images/world_objects/animated/fountain.json";
import FOUNTAIN_IMG from "../assets/images/world_objects/animated/fountain.png";
import FOUNTAIN2_JSON from "../assets/images/world_objects/animated/fountain2.json";
import FOUNTAIN2_IMG from "../assets/images/world_objects/animated/fountain2.png";
import FOUNTAIN6_JSON from "../assets/images/world_objects/animated/fountain6.json";
import FOUNTAIN6_IMG from "../assets/images/world_objects/animated/fountain6.png";
import { ASSET_KEYS } from "../common/assets";
import { BasePreloadScene } from "./base-preload-scene";
import { SCENE_KEYS } from "./scene-keys";

export class RoyalGrovesPreloadScene extends BasePreloadScene {
  constructor() {
    super(SCENE_KEYS.ROYAL_GROVES_PRELOAD_SCENE);
  }

  public preload(): void {
    super.preload();
    this.#loadRoyalGrovesAssets();
  }

  public create(): void {
    super.create();
    this.#createRoyalGrovesAnimations();
  }

  #loadRoyalGrovesAssets(): void {
    // Load hedge level
    this.load.image(ASSET_KEYS.HEDGE_BACKGROUND, HEDGE_BACKGROUND);
    this.load.image(ASSET_KEYS.HEDGE_FOREGROUND, HEDGE_FOREGROUND);
    this.load.tilemapTiledJSON(ASSET_KEYS.HEDGE_LEVEL, HEDGE_LEVEL);

    this.load.aseprite(ASSET_KEYS.STUMP, STUMP_IMG, STUMP_JSON);
    this.load.aseprite(ASSET_KEYS.BULB, BULB_IMG, BULB_JSON);
    this.load.aseprite(ASSET_KEYS.ROCK, ROCK_IMG, ROCK_JSON);
    this.load.aseprite(ASSET_KEYS.SEED, SEED_IMG, SEED_JSON);
    this.load.aseprite(ASSET_KEYS.VSPROUT, VSPROUT_IMG, VSPROUT_JSON);

    // Load animated objects assets
    this.load.aseprite(ASSET_KEYS.FOUNTAIN, FOUNTAIN_IMG, FOUNTAIN_JSON);
    this.load.aseprite(ASSET_KEYS.FOUNTAIN2, FOUNTAIN2_IMG, FOUNTAIN2_JSON);
    this.load.aseprite(ASSET_KEYS.FOUNTAIN6, FOUNTAIN6_IMG, FOUNTAIN6_JSON);

    // Load hedge data
    this.load.json(ASSET_KEYS.EVENTS, HEDGE_EVENTS);
    this.load.json(ASSET_KEYS.NPCS, HEDGE_NPCS);

    // Load spot the difference assets
    const spotAssets = [
      { key: "trees1", img: TREES1_IMG, json: TREES1_JSON },
      { key: "trees2", img: TREES2_IMG, json: TREES2_JSON },
      { key: "trees3", img: TREES3_IMG, json: TREES3_JSON },
      { key: "trees4", img: TREES4_IMG, json: TREES4_JSON },
    ];
    for (const spot of spotAssets) {
      this.load.image(spot.key, spot.img);
      this.load.json(`${spot.key}_data`, spot.json);
    }
  }

  #createRoyalGrovesAnimations(): void {
    this.anims.createFromAseprite(ASSET_KEYS.STUMP);
    this.anims.createFromAseprite(ASSET_KEYS.BULB);
    this.anims.createFromAseprite(ASSET_KEYS.ROCK);
    this.anims.createFromAseprite(ASSET_KEYS.SEED);
    this.anims.createFromAseprite(ASSET_KEYS.VSPROUT);
    this.anims.createFromAseprite(ASSET_KEYS.FOUNTAIN);
    this.anims.createFromAseprite(ASSET_KEYS.FOUNTAIN2);
    this.anims.createFromAseprite(ASSET_KEYS.FOUNTAIN6);
  }
}
