import { GameOverScene } from "../scenes/game-over-scene";
import { RoyalGrovesGameScene } from "../scenes/royal_groves-game-scene";
import { RoyalGrovesPreloadScene } from "../scenes/royal_groves-preload-scene";
import { SCENE_KEYS } from "../scenes/scene-keys";
import { SpotTheDifferenceScene } from "../scenes/spot-the-difference/spot-the-difference-scene";
import { UIScene } from "../scenes/ui-scene";
import type { SceneLoader } from "./types";

export const loadRoyalGrovesScenes: SceneLoader = (game) => {
  game.scene.add(
    SCENE_KEYS.ROYAL_GROVES_PRELOAD_SCENE,
    RoyalGrovesPreloadScene,
    false,
  );
  game.scene.add(
    SCENE_KEYS.ROYAL_GROVES_GAME_SCENE,
    RoyalGrovesGameScene,
    false,
  );
  game.scene.add(SCENE_KEYS.UI_SCENE, UIScene, false);
  game.scene.add(SCENE_KEYS.GAME_OVER_SCENE, GameOverScene, false);
  game.scene.add(
    SCENE_KEYS.SPOT_THE_DIFFERENCE_SCENE,
    SpotTheDifferenceScene,
    false,
  );
  game.scene.start(SCENE_KEYS.ROYAL_GROVES_PRELOAD_SCENE);
};
