import { type TeamHuntState } from "@hunt/public-client";
import React from "react";
import { hydrateRoot } from "react-dom/client";
import { ErrataDataProvider } from "../../../client/ErrataProvider";
import GameworldZoneClient from "../../../components/overworld/GameworldZoneClient";
import { loadRoyalGrovesScenes } from "../gameworld/scene-loaders/royal_groves";
import RoyalGrovesBody from "./RoyalGrovesBody";
import { type RoyalGrovesState } from "./types";

const RoyalGrovesManager = ({
  initialState,
  initialTeamState,
}: {
  initialState: RoyalGrovesState;
  initialTeamState: TeamHuntState;
}) => {
  return (
    <ErrataDataProvider initialTeamState={initialTeamState}>
      <GameworldZoneClient
        roundSlug="royal_groves"
        initialState={initialState}
        initialTeamState={initialTeamState}
        sceneLoader={loadRoyalGrovesScenes}
        render={({ state, teamState, gameNode }) => {
          return (
            <RoyalGrovesBody
              state={state}
              teamState={teamState}
              gameNode={gameNode}
            />
          );
        }}
      />
    </ErrataDataProvider>
  );
};

const elem = document.getElementById("royal_groves-root");
if (elem) {
  const { initialRoyalGrovesState: state, initialTeamState } =
    window as unknown as {
      initialRoyalGrovesState: RoyalGrovesState;
      initialTeamState: TeamHuntState;
    };
  hydrateRoot(
    elem,
    <RoyalGrovesManager
      initialState={state}
      initialTeamState={initialTeamState}
    />,
  );
} else {
  console.error(
    "Could not mount RoyalGrovesManager because #royal_groves-root was nowhere to be found",
  );
}
